// SPDX-License-Identifier: MIT
import assert from 'node:assert/strict';
import { mkdtempSync, mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';

const script = join(dirname(fileURLToPath(import.meta.url)), 'check-links.mjs');
const fixture = mkdtempSync(join(dirname(script), '.asset-validation-link-check-'));
const write = (path, contents = '') => writeFileSync(join(fixture, path), contents);
const run = () => spawnSync(process.execPath, [script, fixture], { encoding: 'utf8' });

try {
  for (const directory of ['readme-dir', 'index-dir', 'empty-dir']) mkdirSync(join(fixture, directory));
  write('readme-dir/README.md');
  write('index-dir/index.md');
  write('file.md');
  write('links.md', [
    '[README](readme-dir/) [index](index-dir/) [file](file.md)',
    '```md',
    '[fenced missing](missing.md)',
    '```',
  ].join('\n'));

  const valid = run();
  assert.equal(valid.status, 0, valid.stderr);
  assert.match(valid.stdout, /Checked 3 local Markdown file links\./);

  write('links.md', '[README](readme-dir/) [empty](empty-dir/)');
  const invalid = run();
  assert.equal(invalid.status, 1, invalid.stdout);
  assert.match(invalid.stderr, /links\.md:1: empty-dir\//);
  console.log('Directory link checks passed (README.md, index.md, empty directory, file, and fence).');
} finally {
  rmSync(fixture, { recursive: true, force: true });
}

